# Completa la línea marcada y compruébala con py check.
def severidad(impacto, probabilidad):
    p = impacto * probabilidad
    if p == 9:
        return "crítica"
    if p >= 6:
        return "alta"
    return "baja"   # ← cambia esta línea: falta el tramo «media» (3 o más)

print(severidad(2, 3))   # alta
